/**
 * Compiles specs/*.yaml into src/specs.generated.ts: each spec's verbatim YAML (served at
 * /m/<id>.yaml) and its parsed data. Validates every file with the Zod schema and the
 * whole set with crossCheck; any problem fails the run, so a broken spec never ships.
 *
 *   pnpm --filter @workspace/metrics specs           write the generated file
 *   pnpm --filter @workspace/metrics specs --check   fail if it is out of date
 *   pnpm --filter @workspace/metrics specs --partial links to unwritten specs only warn
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"
import { parse } from "yaml"
import { crossCheck, metricSpecSchema, type MetricSpec } from "../src/spec.ts"

const root = join(dirname(fileURLToPath(import.meta.url)), "..")
const dir = join(root, "specs")
const out = join(root, "src", "specs.generated.ts")

const files = readdirSync(dir)
  .filter((f) => f.endsWith(".yaml"))
  .sort()
const problems: string[] = []
const entries: { id: string; yaml: string; data: unknown }[] = []
const parsed: MetricSpec[] = []

for (const file of files) {
  const yaml = readFileSync(join(dir, file), "utf8")
  let data: unknown
  try {
    data = parse(yaml)
  } catch (e) {
    problems.push(`${file}: not valid YAML: ${(e as Error).message}`)
    continue
  }
  const res = metricSpecSchema.safeParse(data)
  if (!res.success) {
    for (const issue of res.error.issues) problems.push(`${file}: ${issue.path.join(".") || "(root)"}: ${issue.message}`)
    continue
  }
  if (`${res.data.id}.yaml` !== file) problems.push(`${file}: id "${res.data.id}" must match the file name`)
  entries.push({ id: res.data.id, yaml, data })
  parsed.push(res.data)
}
// --partial: while a family of specs is being written, links to specs not written yet only warn.
const links = crossCheck(parsed)
if (process.argv.includes("--partial")) {
  if (links.length) console.warn(`${links.length} unresolved link${links.length === 1 ? "" : "s"} (allowed with --partial):\n${links.map((p) => `  ${p}`).join("\n")}`)
} else problems.push(...links)

if (problems.length) {
  console.error(`${problems.length} problem${problems.length === 1 ? "" : "s"} in specs:\n${problems.map((p) => `  ${p}`).join("\n")}`)
  process.exit(1)
}

const body = [
  "// Generated by scripts/build-specs.ts from specs/*.yaml. Do not edit; edit the YAML and run `pnpm specs`.",
  "",
  "export const specSources: Record<string, { yaml: string; data: unknown }> = {",
  ...entries.map((e) => `  ${JSON.stringify(e.id)}: { yaml: ${JSON.stringify(e.yaml)}, data: ${JSON.stringify(e.data)} },`),
  "}",
  "",
].join("\n")

if (process.argv.includes("--check")) {
  let current = ""
  try {
    current = readFileSync(out, "utf8")
  } catch {}
  if (current !== body) {
    console.error("src/specs.generated.ts is out of date. Run `pnpm --filter @workspace/metrics specs`.")
    process.exit(1)
  }
  console.log(`${entries.length} specs, generated file up to date.`)
} else {
  writeFileSync(out, body)
  console.log(`${entries.length} specs compiled to src/specs.generated.ts`)
}
